        notes: ['sessions: not a map, defaults applied'],
      );
    }
    final notes = <String>[];
    var retention = const SessionRetentionConfig();
    node.forEach((key, value) {
      switch ('$key') {
        case 'retention':
          retention = SessionRetentionConfig.fromYaml(value);
        default:
          notes.add('sessions.$key: unknown key (i…

