      final fake = FakeStreamFunction([textTurn('ok')]);
      final cli = bootCli(
        fake.call,
        sessionName: target.id,
        sessions: retention(),
      );
      final run = cli.run();
      await waitForIt(
        () => !cli.isBusy && bootIo.out.toString().contains('ok'),
        reason: 'the scripted first turn completes',
      );
      bootIo.sendLine('/exit');
      await run;
