  var json = false;
  var flat = false;
  var dryRun = false;
  String? repairTarget;
  for (var i = 1; i < args.length; i++) {
    switch (args[i]) {
      case '--json' when verb == 'list':
        json = true;
      case '--flat' when verb == 'list':
        flat = true;
      case '--dry-run' when verb == 'repair' || verb == 'clean':
        dryRun = true;
