    this.session,
  });

  /// The foreign harness (`omp`, `kimi`, `opencode`, `claude`).
  final String harness;

  /// `--all`: every discovered current-folder session.
  final bool all;

  /// `--session <id|prefix>`: one session, exact id or unambiguous prefix.
  final String? session;
}

